mapper.select:
SELECT 
FROM rag_document_registry
WHERE tenant_id = #{tenantId}
  AND knowledge_base_id = #{knowledgeBaseId}
  AND deleted = 0
ORDER BY updated_at DESC

SELECT 
FROM rag_document_registry
WHERE tenant_id = #{tenantId}
  AND knowledge_base_id = #{knowledgeBaseId}
  AND document_id = #{documentId}
  AND deleted = 0

mapper.update:
UPDATE rag_document_registry
SET deleted = 1,
    deleted_at = CURRENT_TIMESTAMP(3),
    updated_at = CURRENT_TIMESTAMP(3)
WHERE tenant_id = #{tenantId}
  AND knowledge_base_id = #{knowledgeBaseId}
  AND document_id = #{documentId}
  AND deleted = 0

mapper.delete:
DELETE FROM rag_import_document
WHERE tenant_id = #{tenantId}
  AND import_batch_id = #{importBatchId}

mapper.select:
SELECT 
FROM rag_import_batch
WHERE tenant_id = #{tenantId}
  AND import_batch_id = #{importBatchId}

SELECT document_id
FROM rag_import_document
WHERE tenant_id = #{tenantId}
  AND import_batch_id = #{importBatchId}
ORDER BY id ASC
